    private void showChatDialog() {
        final Dialog chatDialog = new Dialog(VoiceRoomActivity.this, R.style.Theme_Design_BottomSheetDialog);
        chatDialog.requestWindowFeature(Window.FEATURE_NO_TITLE); chatDialog.setContentView(R.layout.dialog_bottom_chat);
        Window window = chatDialog.getWindow(); if(window!=null){ window.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT); window.setGravity(Gravity.BOTTOM); window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_VISIBLE); }
        EditText inputMsg = chatDialog.findViewById(R.id.editRoomMessage); Button btnSendMsg = chatDialog.findViewById(R.id.btnSendRoomMessage);
        if(btnSendMsg!=null && inputMsg!=null) btnSendMsg.setOnClickListener(view -> {
            String message=inputMsg.getText().toString().trim(); String userName=prefs.getString("USER_NAME","User");
            if(!message.isEmpty()){ String msgId=messagesRef.push().getKey(); if(msgId!=null){ java.util.Map<String,Object> m=new java.util.HashMap<>(); m.put("senderName", getCorrectBadgeIcon(currentUserId)+userName); m.put("senderId", currentUserId); m.put("message", message); m.put("timestamp", System.currentTimeMillis()); messagesRef.child(msgId).setValue(m); } inputMsg.setText(""); chatDialog.dismiss(); }
        }); chatDialog.show();
    }
    private void showPremiumRankingDialog() {
        final Dialog rankDialog = new Dialog(this, android.R.style.Theme_Black_NoTitleBar_Fullscreen); rankDialog.requestWindowFeature(Window.FEATURE_NO_TITLE); rankDialog.setContentView(R.layout.dialog_room_ranking);
        TextView btnClose = rankDialog.findViewById(R.id.btnCloseRanking); if(btnClose!=null) btnClose.setOnClickListener(v -> rankDialog.dismiss());
        Button btnTabDaily = rankDialog.findViewById(R.id.btnTabDaily); Button btnTabWeekly = rankDialog.findViewById(R.id.btnTabWeekly); Button btnTabMonthly = rankDialog.findViewById(R.id.btnTabMonthly);
        LinearLayout listContainer = rankDialog.findViewById(R.id.rankingListContainer);
        LinearLayout premiumTop = new LinearLayout(this); premiumTop.setOrientation(LinearLayout.HORIZONTAL); premiumTop.setGravity(Gravity.CENTER); premiumTop.setPadding(0,20,0,10);
        Button btnWealth=new Button(this); btnWealth.setText("💰 Wealth"); Button btnCharm=new Button(this); btnCharm.setText("❤️ Charm"); premiumTop.addView(btnWealth); premiumTop.addView(btnCharm);
        Runnable loadRank = () -> {
            btnWealth.setBackgroundColor(rankTab.equals("Wealth")?Color.parseColor("#FFD700"):Color.parseColor("#2A1B4E")); btnWealth.setTextColor(rankTab.equals("Wealth")?Color.BLACK:Color.WHITE);
            btnCharm.setBackgroundColor(rankTab.equals("Charm")?Color.parseColor("#FF4081"):Color.parseColor("#2A1B4E")); btnCharm.setTextColor(Color.WHITE);
            userDatabaseRef.orderByChild(rankTab.equals("Wealth")?"sendingCoins":"receivingCoins").limitToLast(20).addValueEventListener(new ValueEventListener(){
                @Override public void onDataChange(@NonNull DataSnapshot snap){ rankCache.clear(); for(DataSnapshot ds: snap.getChildren()){ String n=ds.child("name").getValue(String.class); Long c=ds.child(rankTab.equals("Wealth")?"sendingCoins":"receivingCoins").getValue(Long.class); String img=ds.child("profileImage").getValue(String.class); if(n==null) n="User"; rankCache.add(new RankItem(n,c!=null?c:0L,img,ds.getKey())); } Collections.sort(rankCache,(a,b)->Long.compare(b.coins,a.coins)); if(listContainer!=null){ listContainer.removeAllViews(); if(rankCache.size()>=3){ LinearLayout podium=new LinearLayout(VoiceRoomActivity.this); podium.setOrientation(LinearLayout.HORIZONTAL); podium.setGravity(Gravity.BOTTOM|Gravity.CENTER); podium.setPadding(0,10,0,15); podium.addView(makePodiumItem(rankCache.get(1),"🥈 Top 2",false)); podium.addView(makePodiumItem(rankCache.get(0),"👑 Top 1",true)); podium.addView(makePodiumItem(rankCache.get(2),"🥉 Top 3",false)); listContainer.addView(podium); } for(int i=0;i<rankCache.size();i++){ String badge=i==0?"#FFD700":i==1?"#C0C0C0":i==2?"#CD7F32":"#FFFFFF"; String label=i<3?"🏆 Top "+(i+1)+" • "+rankCache.get(i).name:(i+1)+". "+rankCache.get(i).name; addRankUserRow(listContainer,String.valueOf(i+1),label,rankCache.get(i).coins+" Coins",badge); } if(rankCache.isEmpty()) addRankUserRow(listContainer,"1","No Ranking Yet - Send Gift to Rank Up","0 Coins","#FFD700"); } }
                @Override public void onCancelled(@NonNull DatabaseError e){}
            });
        };
        btnWealth.setOnClickListener(v->{ rankTab="Wealth"; loadRank.run(); }); btnCharm.setOnClickListener(v->{ rankTab="Charm"; loadRank.run(); });
        if(btnTabDaily!=null) btnTabDaily.setOnClickListener(v->{ rankPeriod="Day"; loadRank.run(); }); if(btnTabWeekly!=null) btnTabWeekly.setOnClickListener(v->{ rankPeriod="Week"; loadRank.run(); }); if(btnTabMonthly!=null) btnTabMonthly.setOnClickListener(v->{ rankPeriod="Month"; loadRank.run(); });
        try{ ViewGroup parent=(ViewGroup)listContainer.getParent(); parent.addView(premiumTop,0); }catch(Exception ignored){}
        loadRank.run(); rankDialog.show();
    }
    private LinearLayout makePodiumItem(RankItem item, String topText, boolean isTop1){ LinearLayout box=new LinearLayout(this); box.setOrientation(LinearLayout.VERTICAL); box.setGravity(Gravity.CENTER); box.setLayoutParams(new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f)); TextView crown=new TextView(this); crown.setText(isTop1?"👑":""); crown.setTextSize(22); crown.setGravity(Gravity.CENTER); box.addView(crown); ImageView avatar=new ImageView(this); LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(isTop1?170:130,isTop1?170:130); ap.gravity=Gravity.CENTER; avatar.setLayoutParams(ap); if(item.image!=null && !item.image.isEmpty()){ try{ byte[] b=android.util.Base64.decode(item.image,android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(b,0,b.length); if(bmp!=null){ RoundedBitmapDrawable d=RoundedBitmapDrawableFactory.create(getResources(),bmp); d.setCircular(true); avatar.setImageDrawable(d); } }catch(Exception e){ avatar.setImageResource(android.R.drawable.ic_menu_my_calendar); } } else avatar.setImageResource(android.R.drawable.ic_menu_my_calendar); box.addView(avatar); TextView top=new TextView(this); top.setText(topText); top.setTextColor(isTop1?Color.parseColor("#FFD700"):Color.WHITE); top.setTypeface(null,android.graphics.Typeface.BOLD); top.setTextSize(isTop1?15:12); top.setGravity(Gravity.CENTER); if(isTop1) top.setBackgroundColor(Color.parseColor("#B71C1C")); box.addView(top); TextView n=new TextView(this); n.setText(item.name); n.setTextColor(Color.WHITE); n.setTextSize(12); n.setGravity(Gravity.CENTER); box.addView(n); TextView c=new TextView(this); c.setText("🪙 "+item.coins); c.setTextColor(Color.parseColor("#FFD700")); c.setTextSize(11); c.setGravity(Gravity.CENTER); box.addView(c); return box; }
    private void addRankUserRow(LinearLayout container, String rank, String name, String score, String badgeColorHex){ Context ctx=container.getContext(); LinearLayout row=new LinearLayout(ctx); row.setOrientation(LinearLayout.HORIZONTAL); row.setPadding(20,20,20,20); row.setGravity(Gravity.CENTER_VERTICAL); GradientDrawable rBg=new GradientDrawable(); rBg.setColor(Color.parseColor("#1B1035")); rBg.setCornerRadius(16); row.setBackground(rBg); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT); p.setMargins(0,0,0,12); row.setLayoutParams(p); TextView rankTxt=new TextView(ctx); rankTxt.setText("Top "+rank); rankTxt.setTextColor(Color.parseColor(badgeColorHex)); rankTxt.setTextSize(14); rankTxt.setTypeface(null,android.graphics.Typeface.BOLD); rankTxt.setMinWidth(90); row.addView(rankTxt); LinearLayout stack=new LinearLayout(ctx); stack.setOrientation(LinearLayout.VERTICAL); stack.setLayoutParams(new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1.0f)); TextView nameTxt=new TextView(ctx); nameTxt.setText(name); nameTxt.setTextColor(Color.WHITE); nameTxt.setTextSize(15); stack.addView(nameTxt); TextView scoreTxt=new TextView(ctx); scoreTxt.setText(score); scoreTxt.setTextColor(Color.parseColor("#00E676")); scoreTxt.setTextSize(12); stack.addView(scoreTxt); row.addView(stack); container.addView(row); }
    static class RankItem{ String name; long coins; String image; String uid; RankItem(String n,long c,String i,String u){ name=n; coins=c; image=i; uid=u; } }
    private void showPremiumGiftPanel(){ BottomSheetDialog d=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(35,35,35,35); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#1B1035"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg); TextView title=new TextView(this); title.setText("🎁 SR VIP Luxury Gift Center"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setPadding(0,0,0,20); root.addView(title); final EditText inputTarget=new EditText(this); inputTarget.setHint("Target Seat (0 to 9 or All)"); inputTarget.setHintTextColor(Color.parseColor("#AAAAAA")); inputTarget.setTextColor(Color.WHITE); inputTarget.setText("All"); root.addView(inputTarget); RecyclerView rv=new RecyclerView(this); rv.setLayoutManager(new GridLayoutManager(this,3)); rv.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,900)); root.addView(rv); List<GiftModel> gifts=new ArrayList<>(); gifts.add(new GiftModel("g1","White Tiger","50,000",R.drawable.ic_gift_flower,"Animal")); gifts.add(new GiftModel("g2","Golden Lion","100,000",R.drawable.ic_gift_ring,"Animal")); gifts.add(new GiftModel("g3","Royal Dragon","250,000",R.drawable.ic_gift_diamond,"Animal")); gifts.add(new GiftModel("g4","Super Sports Car","500,000",R.drawable.ic_gift_car,"Vehicle")); gifts.add(new GiftModel("g5","VIP Helicopter","750,000",R.drawable.ic_gift_car,"Vehicle")); gifts.add(new GiftModel("g6","Royal Crown","1,000,000",R.drawable.ic_gift_crown,"Crown")); gifts.add(new GiftModel("g7","Diamond Castle","1,250,000",R.drawable.ic_gift_castle,"Castle")); gifts.add(new GiftModel("g8","Luxury Jet Plane","1,500,000",R.drawable.ic_gift_car,"Vehicle")); gifts.add(new GiftModel("g9","Golden Empire","1,800,000",R.drawable.ic_gift_castle,"Castle")); gifts.add(new GiftModel("g10","Mega Titan Dragon","2,200,000",R.drawable.ic_gift_diamond,"Animal")); gifts.add(new GiftModel("g11","Ultimate Supreme","2,500,000",R.drawable.ic_gift_crown,"Crown")); gifts.add(new GiftModel("g12","SR Universe King","3,000,000",R.drawable.ic_gift_castle,"Crown")); final GiftModel[] sel={gifts.get(0)}; GiftAdapter ad=new GiftAdapter(gifts,gift->sel[0]=gift); rv.setAdapter(ad); Button btnSend=new Button(this); btnSend.setText("🚀 Send Luxury Gift"); btnSend.setBackgroundColor(Color.parseColor("#FF4081")); btnSend.setTextColor(Color.WHITE); LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,120); bp.setMargins(0,20,0,10); btnSend.setLayoutParams(bp); root.addView(btnSend); d.setContentView(root); btnSend.setOnClickListener(v->{ String targetVal=inputTarget.getText().toString().trim(); String userName=prefs.getString("USER_NAME","User"); String priceStr=sel[0].getGiftPrice().replaceAll("[^0-9]",""); long giftCoins=priceStr.isEmpty()?50000L:Long.parseLong(priceStr); triggerFlyingGiftAnimation(sel[0].getGiftName()); if(targetVal.equalsIgnoreCase("All")){ databaseReference.child("seats").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ for(int i=0;i<10;i++){ String k="seat_"+i; if(snap.hasChild(k)){ Long cur=snap.child(k).child("giftTotal").getValue(Long.class); databaseReference.child("seats").child(k).child("giftTotal").setValue((cur!=null?cur:0L)+giftCoins); String sid=snap.child(k).child("userId").getValue(String.class); if(sid!=null && !sid.isEmpty()) updateReceivingCoinsForUser(sid,giftCoins); } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); } else { try{ int idx=Integer.parseInt(targetVal); if(idx>=0 && idx<=9){ String k="seat_"+idx; databaseReference.child("seats").child(k).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ Long cur=snap.child("giftTotal").getValue(Long.class); databaseReference.child("seats").child(k).child("giftTotal").setValue((cur!=null?cur:0L)+giftCoins); String sid=snap.child("userId").getValue(String.class); if(sid!=null && !sid.isEmpty()) updateReceivingCoinsForUser(sid,giftCoins); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } }catch(Exception e){} } if(!currentUserId.isEmpty()) userDatabaseRef.child(currentUserId).child("sendingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(currentUserId).child("sendingCoins").setValue((cur!=null?cur:0L)+giftCoins); } @Override public void onCancelled(@NonNull DatabaseError e){} }); String msgId=messagesRef.push().getKey(); if(msgId!=null){ java.util.Map<String,Object> m=new java.util.HashMap<>(); m.put("senderName",getCorrectBadgeIcon(currentUserId)+"🎁 "+userName); m.put("message","sent luxury gift ["+sel[0].getGiftName()+" - "+sel[0].getGiftPrice()+" Coins]"); m.put("timestamp",System.currentTimeMillis()); messagesRef.child(msgId).setValue(m); } Toast.makeText(this,"Luxury Gift Sent!",Toast.LENGTH_SHORT).show(); d.dismiss(); }); d.show(); Window w=d.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1500); w.setGravity(Gravity.BOTTOM); } }
    private void updateReceivingCoinsForUser(String uid,long c){ userDatabaseRef.child(uid).child("receivingCoins").addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ Long cur=s.getValue(Long.class); userDatabaseRef.child(uid).child("receivingCoins").setValue((cur!=null?cur:0L)+c); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private void triggerFlyingGiftAnimation(String giftName){ try{ ViewGroup rootView=findViewById(android.R.id.content); if(rootView==null) return; final TextView fv=new TextView(this); fv.setText("🎁 "+giftName+" 🚀"); fv.setTextColor(Color.parseColor("#FFD700")); fv.setTextSize(20); fv.setTypeface(null,android.graphics.Typeface.BOLD); fv.setGravity(Gravity.CENTER); fv.setBackgroundColor(Color.parseColor("#88000000")); fv.setPadding(30,20,30,20); FrameLayout.LayoutParams params=new FrameLayout.LayoutParams(ViewGroup.LayoutParams.WRAP_CONTENT,ViewGroup.LayoutParams.WRAP_CONTENT); params.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL; params.setMargins(0,0,0,300); rootView.addView(fv,params); TranslateAnimation anim=new TranslateAnimation(Animation.ABSOLUTE,0f,Animation.ABSOLUTE,0f,Animation.ABSOLUTE,0f,Animation.ABSOLUTE,-1000f); anim.setDuration(2000); anim.setFillAfter(true); anim.setAnimationListener(new Animation.AnimationListener(){ @Override public void onAnimationStart(Animation a){} @Override public void onAnimationEnd(Animation a){ rootView.removeView(fv);} @Override public void onAnimationRepeat(Animation a){} }); fv.startAnimation(anim); }catch(Exception ignored){} }
    private void listenToRoomAdmins(){ adminsRef.addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ roomAdminList.clear(); for(DataSnapshot ds:s.getChildren()) if(Boolean.TRUE.equals(ds.getValue(Boolean.class))) roomAdminList.add(ds.getKey()); } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private String getCorrectBadgeIcon(String uid){ if(uid==null||uid.isEmpty()) return ""; if(uid.equals(roomOwnerId)||roomAdminList.contains(uid)) return "🛡️ "; return ""; }
    private void listenToRealtimeChatMessages(){ messagesRef.addChildEventListener(new ChildEventListener(){ @Override public void onChildAdded(@NonNull DataSnapshot snap,@Nullable String prev){ String sn=snap.child("senderName").getValue(String.class); String msg=snap.child("message").getValue(String.class); Long t=snap.child("timestamp").getValue(Long.class); if(t!=null && t<roomJoinTimestamp) return; if(sn!=null && msg!=null){ String full=sn+": "+msg; if(!chatMessages.contains(full)){ chatMessages.add(full); chatAdapter.notifyDataSetChanged(); if(chatListView!=null) chatListView.setSelection(chatMessages.size()-1); } } } @Override public void onChildChanged(@NonNull DataSnapshot s,@Nullable String p){} @Override public void onChildRemoved(@NonNull DataSnapshot s){ chatMessages.clear(); chatAdapter.notifyDataSetChanged(); } @Override public void onChildMoved(@NonNull DataSnapshot s,@Nullable String p){} @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private void showRoomLockPasswordDialog(){ AlertDialog.Builder b=new AlertDialog.Builder(VoiceRoomActivity.this); b.setTitle("🔒 Room Lock Protection"); LinearLayout layout=new LinearLayout(VoiceRoomActivity.this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(50,30,50,30); final EditText input=new EditText(VoiceRoomActivity.this); input.setHint("Enter Room Password..."); input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD); layout.addView(input); b.setView(layout); b.setPositiveButton("Lock Room",(d,w)->{ String pw=input.getText().toString().trim(); if(!pw.isEmpty()){ roomMetaRef.child("roomPassword").setValue(pw); roomMetaRef.child("isLocked").setValue(true); Toast.makeText(this,"Room locked!",Toast.LENGTH_SHORT).show(); } }); b.setNeutralButton("Unlock Room",(d,w)->{ roomMetaRef.child("roomPassword").removeValue(); roomMetaRef.child("isLocked").setValue(false); Toast.makeText(this,"Room Unlocked!",Toast.LENGTH_SHORT).show(); }); b.setNegativeButton("Cancel",(d,w)->d.cancel()); b.show(); }
    private void showScrollableOnlineMembersDialog(){ BottomSheetDialog dialog=new BottomSheetDialog(this,R.style.Theme_Design_BottomSheetDialog); LinearLayout layout=new LinearLayout(this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(40,40,40,40); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{Color.parseColor("#1B1035"),Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); layout.setBackground(bg); TextView title=new TextView(this); title.setText("👥 Active Online Members"); title.setTextColor(Color.parseColor("#00E676")); title.setTextSize(18); title.setTypeface(null,android.graphics.Typeface.BOLD); title.setPadding(0,0,0,20); layout.addView(title); ScrollView sv=new ScrollView(this); sv.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,1200)); sv.setFillViewport(true); LinearLayout container=new LinearLayout(this); container.setOrientation(LinearLayout.VERTICAL); databaseReference.child("online_users").addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot snap){ container.removeAllViews(); int serial=1; for(DataSnapshot ds:snap.getChildren()){ String mn=ds.getValue(String.class); String mu=ds.getKey(); if(mn!=null){ LinearLayout row=new LinearLayout(VoiceRoomActivity.this); row.setOrientation(LinearLayout.HORIZONTAL); row.setPadding(20,20,20,20); row.setGravity(Gravity.CENTER_VERTICAL); GradientDrawable rBg=new GradientDrawable(); rBg.setColor(Color.parseColor("#2A1B4E")); rBg.setCornerRadius(16); row.setBackground(rBg); LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT); lp.setMargins(0,0,0,10); row.setLayoutParams(lp); String badge=(mu!=null && mu.equals(roomOwnerId))?"👑 Owner ":(roomAdminList.contains(mu)?"🛡️ Admin ":"🟢 Member "); TextView nt=new TextView(VoiceRoomActivity.this); nt.setText(serial+". "+badge+mn+" (ID: "+mu+")"); nt.setTextColor(Color.WHITE); nt.setTextSize(15); nt.setTypeface(null,android.graphics.Typeface.BOLD); row.addView(nt); final String fn=mn; final String fu=mu; row.setOnClickListener(v->{ dialog.dismiss(); fetchUserDataAndShowProfile(fn,fu,null); }); container.addView(row); serial++; } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); sv.addView(container); layout.addView(sv); dialog.setContentView(layout); Window w=dialog.getWindow(); if(w!=null){ w.setLayout(ViewGroup.LayoutParams.MATCH_PARENT,1400); w.setGravity(Gravity.BOTTOM); } dialog.show(); }
    private void syncLatestUserProfile(){ if(!currentUserId.isEmpty()) userDatabaseRef.child(currentUserId).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ if(s.exists()){ String dbName=s.child("name").getValue(String.class); String dbImg=s.child("profileImage").getValue(String.class); SharedPreferences.Editor e=prefs.edit(); if(dbName!=null && !dbName.isEmpty()) e.putString("USER_NAME",dbName); if(dbImg!=null){ e.putString("USER_IMAGE",dbImg); e.putString("USER_PROFILE_IMAGE",dbImg); } e.apply(); } } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private void listenToRoomDetails(){ roomMetaRef.addValueEventListener(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String rn=s.child("roomName").getValue(String.class); String rb=s.child("roomBio").getValue(String.class); String oi=s.child("roomOwnerImage").getValue(String.class); if(rn!=null && !rn.isEmpty()){ if(roomTitleText!=null) roomTitleText.setText(rn); } else if(roomTitleText!=null) roomTitleText.setText("SR Voice Room"); if(roomInfoText!=null) roomInfoText.setText("ID: "+roomOwnerId+" 📋 - Copy করতে ক্লিক করো"); if(roomNoticeBarText!=null){ String bio=(rb!=null && !rb.isEmpty())?rb:"Welcome to my voice room!"; roomNoticeBarText.setText("📢 Notice: "+bio); } if(roomHeaderProfileImg!=null && oi!=null && !oi.isEmpty()){ try{ byte[] d=android.util.Base64.decode(oi,android.util.Base64.DEFAULT); Bitmap bmp=BitmapFactory.decodeByteArray(d,0,d.length); if(bmp!=null){ RoundedBitmapDrawable rd=RoundedBitmapDrawableFactory.create(getResources(),bmp); rd.setCircular(true); roomHeaderProfileImg.setImageDrawable(rd); } }catch(Exception e){ roomHeaderProfileImg.setImageResource(android.R.drawable.ic_menu_my_calendar); } } } @Override public void onCancelled(@NonNull DatabaseError e){} }); }
    private void showEditRoomDialog(){ AlertDialog.Builder b=new AlertDialog.Builder(VoiceRoomActivity.this); b.setTitle("⚙️ Room Settings & Profile"); LinearLayout layout=new LinearLayout(VoiceRoomActivity.this); layout.setOrientation(LinearLayout.VERTICAL); layout.setPadding(50,20,50,20); Button btnPic=new Button(VoiceRoomActivity.this); btnPic.setText("🖼️ Change Room Profile Picture"); btnPic.setOnClickListener(v->{ Intent intent=new Intent(Intent.ACTION_PICK, MediaStore.Images.Media.EXTERNAL_CONTENT_URI); startActivityForResult(intent,PICK_IMAGE_REQUEST); }); layout.addView(btnPic); dialogInputName=new EditText(VoiceRoomActivity.this); dialogInputName.setHint("Enter Room Name..."); layout.addView(dialogInputName); dialogInputBio=new EditText(VoiceRoomActivity.this); dialogInputBio.setHint("Enter Room Bio / Notice..."); layout.addView(dialogInputBio); b.setView(layout); b.setPositiveButton("Save",(d,w)->{ String nn=dialogInputName.getText().toString().trim(); String nb=dialogInputBio.getText().toString().trim(); if(!nn.isEmpty()) roomMetaRef.child("roomName").setValue(nn); if(!nb.isEmpty()) roomMetaRef.child("roomBio").setValue(nb); Toast.makeText(this,"Room settings updated!",Toast.LENGTH_SHORT).show(); }); b.setNegativeButton("Cancel",(d,w)->d.cancel()); b.show(); }
    @Override protected void onActivityResult(int requestCode,int resultCode,@Nullable Intent data){ super.onActivityResult(requestCode,resultCode,data); if(requestCode==PICK_IMAGE_REQUEST && resultCode==RESULT_OK && data!=null && data.getData()!=null){ Uri uri=data.getData(); try{ InputStream is=getContentResolver().openInputStream(uri); Bitmap bmp=BitmapFactory.decodeStream(is); if(bmp!=null){ Bitmap resized=Bitmap.createScaledBitmap(bmp,150,150,true); ByteArrayOutputStream baos=new ByteArrayOutputStream(); resized.compress(Bitmap.CompressFormat.JPEG,70,baos); String enc=android.util.Base64.encodeToString(baos.toByteArray(),android.util.Base64.DEFAULT); roomMetaRef.child("roomOwnerImage").setValue(enc); Toast.makeText(this,"Room Profile Picture Updated!",Toast.LENGTH_SHORT).show(); } }catch(Exception e){ Toast.makeText(this,"Failed to load image",Toast.LENGTH_SHORT).show(); } } }
