    private void showFullLevelCenterDialog(){ BottomSheetDialog dialog=new BottomSheetDialog(this, R.style.Theme_Design_BottomSheetDialog); LinearLayout root=new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(35,35,35,35); GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM, new int[]{Color.parseColor("#1B1035"), Color.parseColor("#0A0518")}); bg.setCornerRadii(new float[]{45,45,45,45,0,0,0,0}); root.setBackground(bg); TextView title=new TextView(this); title.setText("🏆 SR Level Center (Lv.1 - Lv.150)"); title.setTextColor(Color.parseColor("#FFD700")); title.setTextSize(18); title.setTypeface(null, android.graphics.Typeface.BOLD); title.setGravity(Gravity.CENTER); title.setPadding(0,0,0,20); root.addView(title); ScrollView scrollView=new ScrollView(this); scrollView.setLayoutParams(new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 1400)); scrollView.setFillViewport(true); LinearLayout listContainer=new LinearLayout(this); listContainer.setOrientation(LinearLayout.VERTICAL); for(int lvl=1;lvl<=150;lvl++){ LinearLayout row=new LinearLayout(this); row.setOrientation(LinearLayout.HORIZONTAL); row.setPadding(25,20,25,20); row.setGravity(Gravity.CENTER_VERTICAL); GradientDrawable rBg=new GradientDrawable(); rBg.setColor(Color.parseColor("#2A1B4E")); rBg.setCornerRadius(20); row.setBackground(rBg); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT); p.setMargins(0,0,0,14); row.setLayoutParams(p); TextView badge=new TextView(this); badge.setText(LevelUtils.getLevelBadgeText(lvl)); badge.setTextColor(Color.WHITE); badge.setTextSize(14); badge.setTypeface(null, android.graphics.Typeface.BOLD); badge.setGravity(Gravity.CENTER); badge.setPadding(20,12,20,12); GradientDrawable bBg=new GradientDrawable(); bBg.setColor(LevelUtils.getLevelColor(lvl)); bBg.setCornerRadius(25); badge.setBackground(bBg); badge.setMinWidth(110); row.addView(badge); LinearLayout textStack=new LinearLayout(this); textStack.setOrientation(LinearLayout.VERTICAL); textStack.setPadding(20,0,0,0); textStack.setLayoutParams(new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1.0f)); TextView titleTxt=new TextView(this); titleTxt.setText("Level Badge Tier "+lvl); titleTxt.setTextColor(Color.WHITE); titleTxt.setTextSize(15); titleTxt.setTypeface(null, android.graphics.Typeface.BOLD); textStack.addView(titleTxt); TextView targetTxt=new TextView(this); targetTxt.setText("Target: "+LevelUtils.getLevelTargetCoinsFormatted(lvl)); targetTxt.setTextColor(Color.parseColor("#00E676")); targetTxt.setTextSize(12); textStack.addView(targetTxt); row.addView(textStack); listContainer.addView(row); } scrollView.addView(listContainer); root.addView(scrollView); dialog.setContentView(root); Window window=dialog.getWindow(); if(window!=null){ window.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, 1600); window.setGravity(Gravity.BOTTOM); } dialog.show(); }
    private void takeSeat(int seatIndex, String seatKey){ final String userName=prefs.getString("USER_NAME","User"); final String userImageUriStr=prefs.getString("USER_PROFILE_IMAGE", prefs.getString("USER_IMAGE","")); for(int i=0;i<10;i++){ final int oldIndex=i; databaseReference.child("seats").child("seat_"+i).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String sUserId=s.child("userId").getValue(String.class); if(sUserId!=null && sUserId.equals(currentUserId)) databaseReference.child("seats").child("seat_"+oldIndex).removeValue(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } databaseReference.child("seats").child(seatKey).child("userId").setValue(currentUserId); databaseReference.child("seats").child(seatKey).child("userName").setValue(userName); databaseReference.child("seats").child(seatKey).child("userImage").setValue(userImageUriStr); databaseReference.child("seats").child(seatKey).child("giftTotal").setValue(0L); databaseReference.child("seats").child(seatKey).onDisconnect().removeValue(); Toast.makeText(VoiceRoomActivity.this,"Joined seat successfully!",Toast.LENGTH_SHORT).show(); }
    private void leaveRoomAndFinish(){ databaseReference.child("online_users").child(currentUserId).removeValue(); for(int index=0;index<10;index++){ final int i=index; databaseReference.child("seats").child("seat_"+i).addListenerForSingleValueEvent(new ValueEventListener(){ @Override public void onDataChange(@NonNull DataSnapshot s){ String sUserId=s.child("userId").getValue(String.class); if(sUserId!=null && sUserId.equals(currentUserId)) databaseReference.child("seats").child("seat_"+i).removeValue(); } @Override public void onCancelled(@NonNull DatabaseError e){} }); } finish(); }
